+
+export function normalizeErrorStackOptions(
+  input: unknown
+): NormalizedErrorStackOptions | undefined {
+  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
+    return undefined;
+  }
+
+  const options = input as ErrorStackOptions;
+  const mode: ErrorStackMode =
+    options.mode === 'string' || options.mode === 'frames' ? options.mode : 'off';
+  const maxStackLines = options.maxStackLines;
+  const invalidMaxStackLines =
+    maxStackLines !== undefined &&
+    (!Number.isInteger(maxStackLines) || maxStackLines <= 0);
+  const maxCauseDepth = options.maxCauseDepth;
+  const invalidMaxCauseDepth =
+    maxCauseDepth !== undefined && !Number.isInteger(maxCauseDepth);
+
+  const classNames = Array.isArray(options.classFilter)
+    ? options.classFilter.filter((name): name is string => typeof name === 'string')
+    : typeof options.classFilter === 'string'
+      ? [options.classFilter]
+      : [];
+
+  return {
+    mode: invalidMaxStackLines ? 'off' : mode,
+    normalizeNewlines: options.normalizeNewlines === true,
+    trimLeadingWhitespace: options.trimLeadingWhitespace !== false,
+    maxStackLines: invalidMaxStackLines ? undefined : maxStackLines,
