+import { NormalizedErrorStackOptions } from './error-options.js';
+
+export interface StackFrame {
+  raw: string;
+}
+
+export function normalizeStackNewlines(stack: string): string {
+  return stack.replace(/\\r\
?/g, '\
');
+}
+
+function trimLines(lines: string[], trimLeadingWhitespace: boolean): string[] {
+  if (!trimLeadingWhitespace) return lines;
+  return lines.map((line, index) => (index === 0 ? line : line.replace(/^\\s+/, '')));
+}
+
+function isInternalFrame(line: string, mode: NormalizedErrorStackOptions['stripInternalFrames']): boolean {
+  const node = line.includes('node:internal');
+  const superjson = /src\\/(?:transformer|plainer|index)\\.ts/.test(line);
+  return (
+    (mode === 'node' && node) ||
+    (mode === 'superjson' && superjson) ||
+    (mode === 'node_and_superjson' && (node || superjson))
+  );
+}
+
+function stripFrames(lines: string[], options: NormalizedErrorStackOptions): string[] {
+  return lines.filter((line, index) => index === 0 || !isInternalFrame(line, options.stripInternalFrames));
+}
+
+function redactLine(line: string, options: NormalizedErrorStackOptions): string {
+  if (options.redactPaths === 'strip_cwd') {
+    const cwd = process.cwd().replace(/\\\\/g, '/');
+    return line.replace(new RegExp(escapeRegExp(cwd), 'g'), '');
+  }
+  if (options.redactPaths === 'basename') {
+    return line.replace(/(?:[A-Za-z]:)?(?:\\/|\\\\)[^\\s():]+/g, value => {
+      const segments = value.split(/[\\\\/]/);
+      return segments[segments.length - 1];
+    });
+  }
+  return line;
+}
+
+function redactLines(lines: string[], options: NormalizedErrorStackOptions): string[] {
+  return lines.map(line => redactLine(line, options));
+}
+
+function escapeRegExp(value: string): string {
+  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');
+}
+
+function initialLines(stack: string, options: NormalizedErrorStackOptions): string[] {
+  return (options.normalizeNewlines ? normalizeStackNewlines(stack) : stack).split('\
');
+}
+
+export function processStackString(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string {
+  let lines = trimLines(initialLines(stack, options), options.trimLeadingWhitespace);
+  lines = redactLines(lines, options);
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  lines = stripFrames(lines, options);
+  return lines.join('\
');
+}
+
+export function processStackFrames(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): StackFrame[] {
+  let lines = trimLines(initialLines(stack, options), options.trimLeadingWhitespace);
+  lines = stripFrames(lines, options);
+  lines = redactLines(lines, options);
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  return lines.map(raw => ({ raw }));
+}
