+function errorUsesStackMode(
+  value: Error,
+  superJson: SuperJSON,
+  mode: 'string' | 'frames'
+): boolean {
+  const options = superJson.errorStackOptions;
+  return (
+    options?.mode === mode &&
+    errorMatchesClassFilter(value, superJson)
+  );
+}
+
+function errorMatchesClassFilter(value: Error, superJson: SuperJSON): boolean {
+  const filter = superJson.errorStackOptions?.classFilter;
+  return !filter || filter.has(value.name);
+}
+
+function errorTransformation<A extends 'Error' | 'Error/stack' | 'Error/frames'>(
+  annotation: A,
+  isApplicable: (value: any, superJson: SuperJSON) => value is Error
+) {
+  return simpleTransformation(
+    isApplicable,
+    annotation,
+    (value, superJson) => serializeError(value, superJson, annotation),
+    (value, superJson) => deserializeError(value, superJson, annotation)
+  );
+}
+
+function serializeError(
+  value: Error,
+  superJson: SuperJSON,
+  annotation: 'Error' | 'Error/stack' | 'Error/frames'
+): Record<string, any> {
+  const context = superJson.getErrorSerializationContext(value);
+  const source = context?.source ?? value;
+  const depth = context?.depth ?? 0;
+  const ancestors = context?.ancestors ?? new Set<Error>([source]);
+  const options = superJson.errorStackOptions;
+  const classMatches = errorMatchesClassFilter(source, superJson);
+  const baseError: Record<string, any> = {
+    name: source.name,
+    message:
+      options?.sanitizeMessage && classMatches
+        ? sanitizeMessage(source.message)
+        : source.message,
+  };
+
+  if (!options) {
+    if ('cause' in source) baseError.cause = (source as any).cause;
+  } else {
+    const cause = (source as any).cause;
+    const keepCause =
+      isError(cause) &&
+      (options.includeCauses === 'direct'
+        ? depth === 0
+        : options.includeCauses === 'deep' && depth < options.maxCauseDepth);
+    if (keepCause && !ancestors.has(cause)) {
+      const nextAncestors = new Set(ancestors);
+      nextAncestors.add(cause);
+      baseError.cause = superJson.createErrorCauseProxy(
+        cause,
+        depth + 1,
+        nextAncestors
+      );
+    }
+  }
+
+  if (typeof AggregateError !== 'undefined' && source instanceof AggregateError) {
+    baseError.errors = source.errors;
+  }
+
+  superJson.allowedErrorProps.forEach(prop => {
+    if (options && (prop === 'stack' || prop === 'stackFrames')) return;
+    baseError[prop] = (source as any)[prop];
+  });
+
+  if (annotation === 'Error/stack' && superJson.allowedErrorProps.includes('stack')) {
+    baseError.stack = processStackString(source.stack ?? '', options!);
+  }
+  if (
+    annotation === 'Error/frames' &&
+    superJson.allowedErrorProps.includes('stackFrames')
+  ) {
+    baseError.stackFrames = processStackFrames(source.stack ?? '', options!);
+  }
+
+  const processor = superJson.errorClassRegistry.getProcessor(source.name);
+  return processor ? processor(baseError) : baseError;
+}
+
+function deserializeError(
+  value: Record<string, any>,
+  superJson: SuperJSON,
+  annotation: 'Error' | 'Error/stack' | 'Error/frames'
+): Error {
+  const error =
+    'errors' in value && typeof AggregateError !== 'undefined'
+      ? new AggregateError(value.errors, value.message, { cause: value.cause })
